+package test.com.sun.javafx.binding;
+
+import java.util.function.Consumer;
+
+import javafx.beans.InvalidationListener;
+import javafx.beans.value.ChangeListener;
+import javafx.beans.value.ObservableValue;
+
+/**
+ * Minimal observable value that can have its value directly manipulated
+ * and can have its fireValueChanged customized.
+ *
+ * @param <T> the type of the value
+ */
+class SimpleObservableValue<T> implements ObservableValue<T> {
+    private final Consumer<SimpleObservableValue<T>> fireValueChanged;
+
+    T value;
+    T oldValue;
+    Object data;
+
+    public SimpleObservableValue(Consumer<SimpleObservableValue<T>> fireValueChanged) {
+        this.fireValueChanged = fireValueChanged;
+    }
+
+    @Override
+    public void addListener(InvalidationListener listener) {
+        throw new UnsupportedOperationException("don't call directly!");
+    }
+
+    @Override
+    public void removeListener(InvalidationListener listener) {
+        throw new UnsupportedOperationException("don't call directly!");
+    }
+
+    @Override
+    public void addListener(ChangeListener<? super T> listener) {
+        throw new UnsupportedOperationException("don't call directly!");
+    }
+
+    @Override
+    public void removeListener(ChangeListener<? super T> listener) {
+        throw new UnsupportedOperationException("don't call directly!");
+    }
+
+    @Override
+    public T getValue() {
+        return value;
+    }
+
+    void setValue(T value) {
+        this.oldValue = this.value;
+        this.value = value;
+    }
+
+    void fireValueChanged() {
+        fireValueChanged.accept(this);
+    }
+}
